// Construction du message selon le type
const { type, emprunteur, proprietaire, livre, reservation } = $input.first().json;

const dateRetour = new Date(reservation.date_fin_prevue).toLocaleDateString('fr-FR');
const dateDebut  = new Date(reservation.date_debut).toLocaleDateString('fr-FR');

const messages = {
  reservation_confirmee: {
    emprunteur: `📚 Bonjour ${emprunteur.nom} ! Votre réservation du livre "${livre.titre}" a bien été enregistrée. Elle est en attente de validation par ${proprietaire.nom}. Date limite de retour : ${dateRetour}.`,
    proprietaire: `🔔 Nouvelle réservation ! ${emprunteur.nom} souhaite emprunter "${livre.titre}" à partir du ${dateDebut}. Connectez-vous sur PageEnsemble pour accepter ou refuser.`
  },
  reservation_acceptee: {
    emprunteur: `✅ Bonne nouvelle ${emprunteur.nom} ! Votre réservation de "${livre.titre}" a été acceptée. Vous avez jusqu'au ${dateRetour} pour le retourner. Caution : ${reservation.montant_caution} FCFA. Contactez ${proprietaire.nom} pour récupérer le livre.`,
    proprietaire: null
  },
  reservation_annulee: {
    emprunteur: `❌ Bonjour ${emprunteur.nom}, votre réservation de "${livre.titre}" a été annulée. Vous pouvez réserver un autre livre sur PageEnsemble.`,
    proprietaire: null
  },
  rappel_retour: {
    emprunteur: `⏰ Rappel : Le livre "${livre.titre}" emprunté chez ${proprietaire.nom} est à retourner dans 3 jours (avant le ${dateRetour}). Merci de le préparer !`,
    proprietaire: null
  },
  livre_en_retard: {
    emprunteur: `🚨 RETARD : Le livre "${livre.titre}" devait être retourné le ${dateRetour}. Veuillez contacter ${proprietaire.nom} dès que possible pour organiser le retour.`,
    proprietaire: `🚨 Le livre "${livre.titre}" prêté à ${emprunteur.nom} est en retard depuis le ${dateRetour}. Contactez-le au ${emprunteur.phone}.`
  },
  livre_retourne: {
    emprunteur: `✅ Retour enregistré ! Merci ${emprunteur.nom} d'avoir rendu "${livre.titre}". Votre caution de ${reservation.montant_caution} FCFA vous sera remboursée par ${proprietaire.nom}.`,
    proprietaire: `📬 ${emprunteur.nom} a retourné "${livre.titre}". Pensez à rembourser la caution de ${reservation.montant_caution} FCFA.`
  }
};

const msg = messages[type] || { emprunteur: null, proprietaire: null };

return [{
  json: {
    type,
    sms_emprunteur:    msg.emprunteur   ? { to: emprunteur.phone,    body: msg.emprunteur   } : null,
    sms_proprietaire:  msg.proprietaire ? { to: proprietaire.phone,  body: msg.proprietaire } : null,
    email_emprunteur:  emprunteur.email && msg.emprunteur   ? { to: emprunteur.email,   subject: `PageEnsemble — ${livre.titre}`, body: msg.emprunteur }   : null,
    email_proprietaire: proprietaire.email && msg.proprietaire ? { to: proprietaire.email, subject: `PageEnsemble — ${livre.titre}`, body: msg.proprietaire } : null,
  }
}];
